import{_ as o,o as e,c as d,ag as r}from"./chunks/framework.KxDd3USm.js";const g=JSON.parse('{"title":"09.1 数据表示与浮点数 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"09-计算机系统基础/01-数据表示与浮点数.md","filePath":"09-计算机系统基础/01-数据表示与浮点数.md"}'),a={name:"09-计算机系统基础/01-数据表示与浮点数.md"};function l(c,t,i,n,s,h){return e(),d("div",null,[...t[0]||(t[0]=[r('<h1 id="_09-1-数据表示与浮点数-★★★" tabindex="-1">09.1 数据表示与浮点数 ★★★ <a class="header-anchor" href="#_09-1-数据表示与浮点数-★★★" aria-label="Permalink to &quot;09.1 数据表示与浮点数 ★★★&quot;">​</a></h1><h3 id="_1-1-为什么不能把负号直接存进去" tabindex="-1">1.1 为什么不能把负号直接存进去 <a class="header-anchor" href="#_1-1-为什么不能把负号直接存进去" aria-label="Permalink to &quot;1.1 为什么不能把负号直接存进去&quot;">​</a></h3><p>计算机只保存 0 和 1，没有纸面上的“−”号，所以约定最高位为<strong>符号位</strong>：0 表示正，1 表示负。由此产生原码、反码和补码。</p><p>设机器字长为 <strong>n 位（含 1 位符号位）</strong>：</p><table tabindex="0"><thead><tr><th>码制</th><th>正数</th><th>负数</th><th>n 位定点整数范围</th><th>0 的表示</th></tr></thead><tbody><tr><td>原码</td><td>符号位 0，数值位为绝对值</td><td>符号位 1，数值位为绝对值</td><td>−(2^(n−1)−1)～+(2^(n−1)−1)</td><td>+0、−0 两种</td></tr><tr><td>反码</td><td>与原码相同</td><td>符号位不变，数值位逐位取反</td><td>同原码</td><td>+0、−0 两种</td></tr><tr><td>补码</td><td>与原码相同</td><td>负数反码末位加 1</td><td><strong>−2^(n−1)～2^(n−1)−1</strong></td><td>只有一种</td></tr><tr><td>移码</td><td>补码的符号位取反</td><td>补码的符号位取反</td><td>数值范围同补码</td><td>只有一种</td></tr></tbody></table><p>以 8 位机器数表示 −18：</p><ol><li>+18 的二进制绝对值是 <code>00010010</code>；</li><li>−18 原码：<code>10010010</code>；</li><li>−18 反码：符号位不动，其余取反 → <code>11101101</code>；</li><li>−18 补码：反码 + 1 → <code>11101110</code>；</li><li>−18 移码：补码符号位取反 → <code>01101110</code>。</li></ol><h3 id="_1-2-移码为什么要-翻符号位" tabindex="-1">1.2 移码为什么要“翻符号位” <a class="header-anchor" href="#_1-2-移码为什么要-翻符号位" aria-label="Permalink to &quot;1.2 移码为什么要“翻符号位”&quot;">​</a></h3><p>补码适合做加减，但直接按无符号数比较时，负数编码反而排在正数后面。浮点数经常要先比较阶码大小，如果每次都先解释正负再比较，硬件会更绕。<strong>移码把整个有符号范围平移到非负编码区间</strong>，使同字长、同偏置的阶码可以按无符号数顺序比较。</p><p>以 4 位为例，补码范围是 −8～7；把补码符号位翻转后，移码恰好按数值从小到大排列：</p><table tabindex="0"><thead><tr><th style="text-align:right;">真值</th><th>4 位补码</th><th>4 位移码</th><th style="text-align:right;">按无符号解释移码</th></tr></thead><tbody><tr><td style="text-align:right;">−3</td><td><code>1101</code></td><td><code>0101</code></td><td style="text-align:right;">5</td></tr><tr><td style="text-align:right;">0</td><td><code>0000</code></td><td><code>1000</code></td><td style="text-align:right;">8</td></tr><tr><td style="text-align:right;">+2</td><td><code>0010</code></td><td><code>1010</code></td><td style="text-align:right;">10</td></tr></tbody></table><p>于是 −3＜0＜2，对应移码无符号值也是 5＜8＜10。这里的“翻符号位”与“加偏置 2^(n−1)”效果相同：4 位时偏置为 8，−3+8=5，编码就是 <code>0101</code>。</p><p><strong>反例</strong>：“移码就是所有位取反”——错。只翻补码的<strong>最高符号位</strong>，其余位保持不变。还要注意：只有字长和偏置相同的移码才能直接比较，不能拿 4 位移码和 8 位移码硬比。</p><p><strong>反例前置</strong>：不能把原码 <code>10010010</code> 整体取反再加 1 得到补码；整体取反会把符号位也翻掉。正确做法是“<strong>原码符号位不变，数值位取反，再加 1</strong>”。另一个更快的方法是：从原码最低位向左找到第一个 1，这个 1 及其右边不变，左边数值位取反，符号位仍为 1。</p><p>为什么日常运算用补码？因为补码能让减法变成加法，并把 +0、−0 合成一个。例如 4 位补码：<code>0011</code>（3）+ <code>1110</code>（−2）=<code>1 0001</code>，丢弃最高进位后是 <code>0001</code>（1）。同一套加法器即可做加减。</p><h3 id="_1-3-范围与溢出" tabindex="-1">1.3 范围与溢出 <a class="header-anchor" href="#_1-3-范围与溢出" aria-label="Permalink to &quot;1.3 范围与溢出&quot;">​</a></h3><p>8 位补码范围的公式代入：</p><ul><li>最小值 = −2^(8−1) = <strong>−128</strong>；</li><li>最大值 = 2^(8−1)−1 = <strong>127</strong>。</li></ul><p>口诀：<strong>补码范围“负边多一个”</strong>。<code>10000000</code> 在 8 位补码中是 −128，不是“负零”。</p><p>补码加法的溢出判据：<strong>同号相加，结果变号，发生溢出</strong>。</p><ul><li><code>01111111</code>（127）+ <code>00000001</code>（1）=<code>10000000</code>，两个正数加出负号 → 溢出；</li><li>正数加负数不会因数值范围发生溢出。</li></ul><p><strong>应试动作</strong>：背“负数原码 → 数值位取反 → +1 得补码；移码只翻补码符号位；n 位补码范围 −2^(n−1)～2^(n−1)−1”。题目给二进制最高位为 1 时，先确认它问的是原码还是补码，不能见 1 就只写负号。</p><hr><h2 id="第二节-浮点数-用有限位数装下极大与极小的数-★★" tabindex="-1">第二节 浮点数：用有限位数装下极大与极小的数 ★★ <a class="header-anchor" href="#第二节-浮点数-用有限位数装下极大与极小的数-★★" aria-label="Permalink to &quot;第二节 浮点数：用有限位数装下极大与极小的数 ★★&quot;">​</a></h2><h3 id="_2-1-通用形式与分工" tabindex="-1">2.1 通用形式与分工 <a class="header-anchor" href="#_2-1-通用形式与分工" aria-label="Permalink to &quot;2.1 通用形式与分工&quot;">​</a></h3><p>浮点数类似科学计数法：</p><p><strong>N = M × R^E</strong></p><ul><li>M：尾数，保存有效数字，<strong>位数决定精度</strong>；</li><li>E：阶码，保存小数点移动距离，<strong>位数决定表示范围</strong>；</li><li>R：基数，二进制机器通常取 2。</li></ul><p>例如二进制 <code>101.101₂</code>：</p><p><code>101.101₂ = 0.101101₂ × 2^3</code>。</p><p>一般题目约定尾数用补码、阶码用移码；若题面另有约定，以题面为准。</p><h3 id="_2-2-规格化" tabindex="-1">2.2 规格化 <a class="header-anchor" href="#_2-2-规格化" aria-label="Permalink to &quot;2.2 规格化&quot;">​</a></h3><p>同一个数可写成很多形式：<code>0.1011×2^3</code>、<code>0.01011×2^4</code> 数值相同，但后者浪费了一位有效精度。<strong>规格化</strong>就是让尾数的最高有效位尽快出现。</p><p>对二进制补码尾数，常用判断：</p><ul><li>正数规格化尾数形如 <code>0.1xxx…</code>；</li><li>负数规格化尾数形如 <code>1.0xxx…</code>；</li><li>即尾数符号位与其后第一位<strong>不同</strong>。</li></ul><p><strong>反例</strong>：把 <code>0.001101×2^5</code> 当作规格化数是错的，它前面有两个无效 0。左移两位、阶码减 2，得到 <code>0.1101×2^3</code>，数值不变，因为尾数乘了 2²，同时指数除以 2²。</p><h3 id="_2-3-浮点加减-先对阶-再运算-再规格化" tabindex="-1">2.3 浮点加减：先对阶，再运算，再规格化 <a class="header-anchor" href="#_2-3-浮点加减-先对阶-再运算-再规格化" aria-label="Permalink to &quot;2.3 浮点加减：先对阶，再运算，再规格化&quot;">​</a></h3><p>机械步骤的动机：两把尺子的刻度不同不能直接相加，必须先把指数统一。</p><p>计算 <code>0.1100×2^5 + 0.1010×2^3</code>：</p><ol><li>对阶：小阶向大阶看齐，阶差 5−3=2；</li><li>小数尾数右移 2 位：<code>0.1010×2^3 = 0.001010×2^5</code>；</li><li>尾数相加：<code>0.110000 + 0.001010 = 0.111010</code>；</li><li>结果：<code>0.111010×2^5</code>，已规格化。</li></ol><p>为什么只让小阶向大阶看齐？若把大阶尾数左移，可能迅速越出尾数字段；小阶尾数右移虽然可能损失低位精度，但不会把整数部分挤爆。</p><h4 id="运算后右规-尾数产生进位" tabindex="-1">运算后右规：尾数产生进位 <a class="header-anchor" href="#运算后右规-尾数产生进位" aria-label="Permalink to &quot;运算后右规：尾数产生进位&quot;">​</a></h4><p>计算：</p><p><code>0.1100×2^3 + 0.1100×2^3</code></p><ol><li>两数阶码相同，不用对阶；</li><li>尾数相加：<code>0.1100+0.1100=1.1000</code>；</li><li>尾数超过 <code>0.xxxx</code> 形式，右移 1 位并把阶码加 1：</li></ol><blockquote><p><code>1.1000×2^3 = 0.1100×2^4</code></p></blockquote><p>数值反验：<code>1.1000₂=1.5</code>，<code>1.5×8=12</code>；<code>0.1100₂=0.75</code>，<code>0.75×16=12</code>，左右相等。口诀是：<strong>尾数右移一位，阶码加一</strong>。</p><h4 id="运算后左规-相减出现前导-0" tabindex="-1">运算后左规：相减出现前导 0 <a class="header-anchor" href="#运算后左规-相减出现前导-0" aria-label="Permalink to &quot;运算后左规：相减出现前导 0&quot;">​</a></h4><p>计算：</p><p><code>0.1011×2^4 − 0.1001×2^4</code></p><ol><li>尾数相减得 <code>0.0010×2^4</code>；</li><li>正尾数应形如 <code>0.1xxx</code>，当前有两个无效前导 0；</li><li>尾数左移 2 位、阶码减 2：</li></ol><blockquote><p><code>0.0010×2^4 = 0.1000×2^2</code></p></blockquote><p>数值反验：<code>0.0010₂×16=2</code>，<code>0.1000₂×4=2</code>。口诀是：<strong>尾数左移几位，阶码就减几</strong>。</p><h4 id="舍入-被移走的低位并非永远直接丢弃" tabindex="-1">舍入：被移走的低位并非永远直接丢弃 <a class="header-anchor" href="#舍入-被移走的低位并非永远直接丢弃" aria-label="Permalink to &quot;舍入：被移走的低位并非永远直接丢弃&quot;">​</a></h4><p>若尾数字段只能保留 4 个小数位，计算中得到 <code>0.101011…</code>：</p><ul><li>直接截断得到 <code>0.1010</code>；</li><li>若题目规定“就近舍入”，观察下一位及后续位，本例被舍部分大于半个最低保留单位，应进 1，得到 <code>0.1011</code>。</li></ul><p>具体采用截断、就近舍入还是其他规则，以题面为准。舍入后若再次产生进位，还要再做一次规格化。</p><p><strong>对阶方向反例</strong>：把 <code>0.1010×2^3</code> 的尾数左移两位去迁就 <code>2^5</code>，会写成 <code>10.10×2^5</code>，数值被放大了 16 倍。正确等值变换是尾数<strong>右移</strong>两位：<code>0.001010×2^5</code>。小阶向大阶靠拢时，“阶码加多少，尾数就右移多少”。</p><p>浮点异常：阶码超过上限是<strong>上溢</strong>；太小而无法表示是<strong>下溢</strong>。尾数右移时被舍弃的低位会造成精度损失。</p><p><strong>应试动作</strong>：背“<strong>阶码定范围，尾数定精度；小阶向大阶看齐；对阶—尾数运算—规格化—舍入</strong>”。题目比较两种格式时，只看谁的阶码长、谁的尾数长即可。</p><hr>',61)])])}const _=o(a,[["render",l]]);export{g as __pageData,_ as default};
